import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"第二卦 坤 坤為地 坤上坤下","description":"周易 - 第二卦 坤 坤為地 坤上坤下","frontmatter":{"title":"第二卦 坤 坤為地 坤上坤下","description":"周易 - 第二卦 坤 坤為地 坤上坤下"},"headers":[],"relativePath":"classics/zhouyi/003.md","filePath":"classics/zhouyi/003.md"}'),l={name:"classics/zhouyi/003.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="坤" tabindex="-1">坤 <a class="header-anchor" href="#坤" aria-label="Permalink to “坤”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元，亨，利牝馬之貞。君子有攸往，先迷後得主，利西南得朋，東北喪朋。安貞吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸亨。牝馬地類，行地無疆，柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行；東北喪朋，乃終有慶。安貞之吉，應地無疆。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>地勢坤，君子以厚德載物。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>履霜，堅冰至。象曰：履霜堅冰，陰始凝也。馴致其道，至堅冰也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>直，方，大，不習無不利。象曰：六二之動，直以方也。不習無不利，地道光也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>含章可貞。或從王事，無成有終。象曰：含章可貞；以時發也。或從王事，知光大也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>括囊；無咎，無譽。象曰：括囊無咎，慎不害也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>黃裳，元吉。象曰：黃裳元吉，文在中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>戰龍於野，其血玄黃。象曰：戰龍於野，其道窮也。</p><h3 id="用六" tabindex="-1">用六 <a class="header-anchor" href="#用六" aria-label="Permalink to “用六”">​</a></h3><p>利永貞。象曰：用六永貞，以大終也。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><p>坤至柔，而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤其道順乎？承天而時行。積善之家，必有餘慶；積不善之家，必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辯之不早辯也。易曰：「履霜堅冰至。」蓋言順也。直其正也，方其義也。君子敬以直內，義以方外，敬義立，而德不孤。「直，方，大，不習無不利」；則不疑其所行也。陰雖有美，含之；以從王事，弗敢成也。地道也，妻道也，臣道也。地道無成，而代有終也。天地變化，草木蕃；天地閉，賢人隱。易曰：「括囊；無咎，無譽。」蓋言謹也。君子黃中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也。陰疑於陽，必戰。為其嫌於無陽也，故稱龍焉。猶未離其類也，故稱血焉。夫玄黃者，天地之雜也，天玄而地黃。</p>',23)])])}const _=e(l,[["render",t]]);export{b as __pageData,_ as default};
